func TestMaxDelayCapsGrowth(t *testing.T) {
	resetCounter()
	uncapped := retry.Delay(retry.Attempts(retry.New(), 4), 100*time.Millisecond)
	start := time.Now()
	_ = retry.Do(uncapped, alwaysFail)
	uncappedElapsed := time.Since(start)
	resetCounter()
	capped := retry.MaxDelay(uncapped, 150*time.Millisecond)
	start = time.Now()
	_ = retry.Do(capped, alwaysFail)
	cappedElapsed := time.Since(start)
	test.AssertTrue(t, uncappedElapsed >= 700*time.Millisecond)
	test.AssertTrue(t, cappedElapsed >= 400*time.Millisecond)
	test.AssertTrue(t, cappedElapsed < uncappedElapsed)
}

func TestJitterClampsFraction(t *testing.T) {
	cfg := retry.Jitter(retry.New(), 5.0)
	test.AssertEqual(t, cfg.JitterFraction, 1.0)
	cfg = retry.Jitter(cfg, -0.5)
	test.AssertEqual(t, cfg.JitterFraction, 0.0)
	cfg = retry.Jitter(cfg, 0.2)
	test.AssertEqual(t, cfg.JitterFraction, 0.2)
}

func TestJitterSpread(t *testing.T) {
	cfg := retry.Jitter(retry.Linear(retry.Delay(retry.Attempts(retry.New(), 2), 100*time.Millisecond)), 0.5)
	elapsedList := []time.Duration{}
	for range 7 {
		start := time.Now()
		retry.Sleep(cfg, 0)
		elapsedList = append(elapsedList, time.Since(start))
	}
	low := elapsedList[0]
	high := elapsedList[0]
	for _, e := range elapsedList {
		test.AssertTrue(t, e >= 45*time.Millisecond)
		test.AssertTrue(t, e <= 200*time.Millisecond)
		if e < low {
			low = e
		}
		if e > high {
			high = e
		}
	}
	test.AssertTrue(t, high-low > 15*time.Millisecond)
}
